function openGoalDetail(id){u.goalId=id;u.goalTab='strength';route('goalDetail');}
function templates(){return header()+TU.templates(D,u);}
function templateEdit(){return TU.templateEdit(D,u.templateDraft);}
function readTemplate(){if(u.route==='templateEdit'&&!u.modal)u.templateDraft=TU.readTemplate(root,u.templateDraft);}
