function templateAdd(eid){const t=u.templateDraft;if(!t.entries.some(e=>e.exerciseId===eid)){const settings=T.settings(D,eid);t.entries.push({exerciseId:eid,...settings.prescription,enabled:true,restSec:settings.restSec,group:''});const muscle=cat(eid).muscle;if(!t.muscles.includes(muscle))t.muscles.push(muscle);}}
