function syncNativeTimer(){if(!A)return;try{const stored=JSON.parse(A.load());if(stored.restTimer){capture();D.restTimer=stored.restTimer;if(D.active)D.active.restUntil=D.restTimer.sessionId===D.active.id?D.restTimer.endAt:0;if(['timer','session'].includes(u.route)&&!u.modal)render();else paintTimer();}}catch(e){}}

function start(eid,repeat=false){capture();if(D.active){if(eid)mutate(()=>M.select(D,eid));u.route='session';u.modal=null;render(false);return;}if(!D.preferences.muscles.length&&!eid){toast('先选择今天的训练部位');return;}if(!mutate(()=>{if(repeat){const last=sortedSessions()[0];if(last)M.begin(D,last.muscles,last.exercises.map(e=>e.exerciseId));else M.begin(D,D.preferences.muscles,eid?[eid]:[]);}else M.begin(D,D.preferences.muscles,eid?[eid]:[]);} ))return;u.route='session';u.modal=null;render(false);}
function previewImport(files){let candidate=M.clone(D),added=0,updated=0,hasPreferences=false,errors=[];for(const f of files){try{if(f.text.trim().startsWith('{')){const result=M.merge(candidate,JSON.parse(f.text));candidate=result.state;added+=result.added;updated+=result.updated;hasPreferences=true;}else if(M.addNote(candidate,f.text,f.id))added++;}catch(e){errors.push(f.name+'：'+e.message);}}
 try{M.validate(candidate);u.importCandidate={state:candidate,summary:`可新增 ${added} 次训练，恢复 ${updated} 次训练中的较新修改。力量目标会合并，原始笔记会保留。`,errors,hasPreferences};}catch(e){u.importCandidate={state:null,summary:'导入内容无效',errors:[...errors,e.message]};}u.modal='import';render();}
